/* Mock exams 1-3: original CLF-C02-style questions written for this hub. Appended to EXAM; MOCK_SETS holds their index ranges. */
window.EXAM = window.EXAM || []; window.MOCK_SETS = window.MOCK_SETS || [];
MOCK_SETS.push({ n: 1, start: EXAM.length, count: 65 });
EXAM.push(["concepts", "A bakery in Cebu runs its order website on one server in a back office. During holiday promos the site crashes, and for the rest of the year the server sits mostly idle. Which cloud benefit addresses BOTH problems?", ["Stop guessing capacity", "Go global in minutes", "Benefit from massive economies of scale", "Trade fixed expense for variable expense"], 0, "With the cloud you can scale up for promos and back down afterwards, so you no longer have to guess and over-buy capacity.", [null, "The bakery's problem is capacity, not reaching other countries.", "Economies of scale explain why AWS prices are low; they don't fix crashes or idle servers.", "Variable expense is about how you pay, not about matching capacity to demand."]],
["concepts", "Which design principle means building a system so that the failure of one component does not bring the whole application down?", ["Design for failure", "Use dedicated hardware", "Scale vertically", "Deploy to a single Availability Zone"], 0, "Designing for failure assumes things will break and removes single points of failure.", [null, "Dedicated hardware does not remove single points of failure.", "A bigger single server is still a single point of failure.", "One AZ is itself a single point of failure."]],
["concepts", "A startup's developers can create a full test environment in five minutes, try an idea, and delete it before lunch. Which advantage of cloud computing does this BEST show?", ["Increased speed and agility", "Higher durability", "Lower data transfer costs", "Data sovereignty"], 0, "Resources are available in minutes, so teams can experiment and innovate faster.", [null, "Durability is about not losing stored data.", "Nothing in the scenario is about data transfer pricing.", "Sovereignty is about where data is legally stored."]],
["concepts", "Which statements describe the AWS Cloud's pay-as-you-go model? (Select TWO.)", ["Customers pay only for the resources they consume", "Customers must sign a three-year contract to start", "Customers can stop paying when they shut resources down", "Customers pay a fixed monthly fee regardless of usage", "Customers must buy servers up front"], [0, 2], "Pay-as-you-go means paying for what you use, with no long-term commitment, and charges stop when resources are removed.", [null, "No contract is needed; commitments like Savings Plans are optional.", null, "That describes a flat-rate model.", "Up-front hardware purchase is the traditional on-premises model."]],
["concepts", "A retail company keeps its customer database in its own data center but runs its new mobile app backend on AWS, with a private connection between the two. Which deployment model is this?", ["Hybrid", "Cloud-native", "On-premises", "Multi-Region"], 0, "Hybrid connects on-premises infrastructure with cloud resources.", [null, "Cloud-native would run everything in the cloud.", "On-premises would run everything in the company's own data center.", "Multi-Region is about several AWS Regions, not on-premises plus cloud."]],
["concepts", "Which pillar of the AWS Well-Architected Framework focuses on using computing resources efficiently as demand changes and as technology evolves?", ["Performance efficiency", "Reliability", "Operational excellence", "Cost optimization"], 0, "Performance efficiency is about selecting and adapting the right resource types and sizes as needs change.", [null, "Reliability is about recovering from failure and meeting demand consistently.", "Operational excellence is about running and monitoring systems and improving processes.", "Cost optimization is about avoiding unnecessary cost."]],
["concepts", "A company wants to reduce the energy and hardware its workloads need, for example by choosing Graviton instances and deleting unused data. Which Well-Architected pillar does this support MOST directly?", ["Sustainability", "Security", "Reliability", "Operational excellence"], 0, "The Sustainability pillar focuses on minimizing the environmental impact of workloads.", [null, "Security protects data and systems.", "Reliability is about recovering from failures.", "Operational excellence is about running and improving operations."]],
["concepts", "Which AWS Cloud Adoption Framework (AWS CAF) perspective helps an organization manage cloud skills, training and organizational change?", ["People", "Platform", "Security", "Operations"], 0, "The People perspective covers culture, workforce transformation and organizational design.", [null, "Platform is about building the cloud architecture.", "Security is about protecting data and workloads.", "Operations is about running cloud services day to day."]],
["concepts", "A company plans to move a self-managed MySQL database to Amazon RDS without changing its application code. Which migration strategy is this?", ["Replatform", "Rehost", "Refactor", "Retire"], 0, "Replatforming makes a small optimization (moving to a managed database) without changing the core architecture.", [null, "Rehost would move the server as-is to EC2.", "Refactor would rebuild the application, often to be cloud-native.", "Retire means switching the application off."]],
["concepts", "Which of the following is an example of horizontal scaling?", ["Adding three more web servers behind a load balancer", "Changing a t3.medium instance to an m7g.2xlarge", "Adding more memory to a database server", "Upgrading an EBS volume from gp2 to gp3"], 0, "Horizontal scaling (scaling out) adds more instances.", [null, "Moving to a bigger instance is vertical scaling.", "Adding memory to one server is vertical scaling.", "Changing a volume type is not scaling out."]],
["concepts", "Why should a company deploy its application across multiple Availability Zones?", ["To remain available if one data center location fails", "To reduce the price of EC2 instances", "To meet data residency rules in other countries", "To get a lower latency connection to every user worldwide"], 0, "Each AZ is isolated, so spreading across AZs keeps the application running when one fails.", [null, "Multi-AZ does not lower instance prices.", "All AZs are in the same Region and country, so this does not address residency.", "AZs are close together; global latency is improved by Regions and edge locations."]],
["concepts", "A company must keep citizens' records inside the one AWS Region its regulator approved and never store copies elsewhere. Which factor is driving its Region choice?", ["Compliance and data residency", "Pricing", "Service availability", "Number of edge locations"], 0, "Legal or regulatory requirements about where data lives are compliance and data residency.", [null, "Price is a valid factor, but not the one described.", "The scenario is not about which services exist in the Region.", "Edge locations don't decide where data is stored."]],
["concepts", "Which AWS CAF phase involves expanding successful pilot projects to the desired scale while realizing business benefits?", ["Scale", "Envision", "Align", "Launch"], 0, "Scale is the final phase: expand production pilots and realize benefits.", [null, "Envision identifies opportunities.", "Align identifies gaps and dependencies.", "Launch delivers the first pilots."]],
["concepts", "A company has 400 physical servers. It wants to know how much it could save by moving to AWS before it starts any migration. Which service helps build this business case?", ["Migration Evaluator", "AWS Application Migration Service", "AWS Database Migration Service", "AWS DataSync"], 0, "Migration Evaluator analyzes the current environment and projects the cost of running on AWS.", [null, "Application Migration Service performs the server migration itself.", "DMS migrates databases.", "DataSync copies files and objects."]],
["concepts", "What does elasticity in the AWS Cloud mean?", ["Automatically adding and removing resources to match demand", "Data is copied to at least three Regions", "A single server can grow without limit", "Prices change hourly based on demand"], 0, "Elasticity means capacity grows and shrinks automatically with load.", [null, "Data is not copied across Regions by default.", "A single server always has a limit.", "That describes Spot pricing dynamics, not elasticity."]],
["concepts", "A company wants an architecture review of its main workload against AWS best practices, and a list of high-risk issues to fix, at no cost. What should it use?", ["AWS Well-Architected Tool", "AWS Trusted Advisor Business-level checks", "AWS Professional Services", "Amazon Inspector"], 0, "The Well-Architected Tool is free in the console and reviews a workload against the six pillars.", [null, "Trusted Advisor checks individual resources, not a workload's architecture, and full checks need a paid plan.", "Professional Services is a paid consulting offering.", "Inspector scans for software vulnerabilities."]],
["security", "Under the AWS shared responsibility model, which task is the customer's responsibility when using Amazon EC2?", ["Patching the guest operating system", "Replacing failed hard drives", "Securing the physical data center", "Maintaining the hypervisor"], 0, "With EC2 (IaaS), the customer manages the guest OS, including patches.", [null, "Hardware is AWS's responsibility.", "Physical security is AWS's responsibility.", "The virtualization layer is AWS's responsibility."]],
["security", "Which responsibilities belong to AWS under the shared responsibility model? (Select TWO.)", ["Physical security of data centers", "Configuring security groups", "Patching the underlying host infrastructure", "Encrypting customer data in S3", "Creating IAM users"], [0, 2], "AWS secures the cloud itself: facilities, hardware and the host infrastructure.", [null, "Security groups are customer configuration.", null, "Choosing to encrypt data is the customer's decision.", "Identity management is the customer's job."]],
["security", "A new developer joins a team. The administrator wants to give the same permissions to all five developers and update them in one place. What should the administrator do?", ["Create an IAM group, attach a policy, and add the developers", "Share one IAM user between all developers", "Give each developer the root user's credentials", "Attach a separate inline policy to each developer"], 0, "Groups let you manage permissions for many users in one place.", [null, "Sharing credentials removes accountability and is a bad practice.", "The root user should never be shared or used daily.", "Separate inline policies must each be updated, which is error-prone."]],
["security", "An application on EC2 needs to read files from an S3 bucket. What is the MOST secure way to give it access?", ["Attach an IAM role to the EC2 instance", "Store an access key in the application code", "Make the bucket public", "Put the root user's access key in an environment variable"], 0, "An IAM role provides temporary, automatically rotated credentials to the instance.", [null, "Keys in code can leak and do not rotate.", "Public buckets expose data to everyone.", "Root keys should not exist, let alone sit on a server."]],
["security", "Which is a recommended practice for the AWS account root user?", ["Enable MFA and use it only for tasks that require root", "Use it for daily administration", "Create access keys for it to use the AWS CLI", "Share it with the operations team for emergencies"], 0, "Protect root with MFA and lock it away; do daily work with other identities.", [null, "Daily use of root increases risk.", "Root access keys should not be created.", "Root credentials should never be shared."]],
["security", "A company runs 15 AWS accounts and wants to make sure that no one in any member account can disable AWS CloudTrail, not even account administrators. What should it use?", ["Service control policies in AWS Organizations", "IAM password policy", "AWS Config conformance packs", "Security groups"], 0, "SCPs set the maximum permissions in member accounts and apply even to their administrators.", [null, "A password policy only governs passwords.", "Config can detect the change but cannot prevent it.", "Security groups filter network traffic."]],
["security", "A website is being flooded with traffic from thousands of sources, making it unavailable. Which AWS service protects against this type of attack and is included automatically at no extra cost?", ["AWS Shield Standard", "AWS Shield Advanced", "Amazon GuardDuty", "AWS Firewall Manager"], 0, "Shield Standard automatically protects all customers against common DDoS attacks at no charge.", [null, "Shield Advanced adds protection and a response team but costs extra.", "GuardDuty detects threats; it doesn't absorb DDoS traffic.", "Firewall Manager manages rules across accounts."]],
["security", "Attackers are sending requests with SQL code hidden in form fields to a website behind an Application Load Balancer. Which service can block these requests?", ["AWS WAF", "AWS Shield Standard", "Amazon Macie", "AWS Artifact"], 0, "AWS WAF inspects HTTP requests and blocks patterns such as SQL injection.", [null, "Shield Standard focuses on network-level DDoS, not malicious request content.", "Macie finds sensitive data in S3.", "Artifact provides compliance reports."]],
["security", "Amazon GuardDuty reports that an EC2 instance is communicating with a known cryptocurrency-mining server. What does GuardDuty do?", ["Continuously analyzes logs and network activity to detect threats", "Scans container images for vulnerable software packages", "Encrypts data stored on EBS volumes", "Stores the company's compliance reports"], 0, "GuardDuty is a threat detection service using CloudTrail, VPC Flow Logs, DNS logs and more.", [null, "That is Amazon Inspector.", "That is EBS encryption with KMS.", "That is AWS Artifact."]],
["security", "A company stores millions of customer documents in Amazon S3 and must find out which ones contain passport numbers. Which service should it use?", ["Amazon Macie", "Amazon Detective", "AWS Security Hub", "Amazon Textract"], 0, "Macie discovers sensitive data such as personal identifiers in S3.", [null, "Detective investigates the root cause of security findings.", "Security Hub aggregates findings; it does not scan documents itself.", "Textract extracts text, but does not classify sensitive data for security."]],
["security", "An auditor asks for proof that AWS data centers meet ISO 27001. Where can the company get the official report?", ["AWS Artifact", "AWS Audit Manager", "AWS Config", "AWS Trusted Advisor"], 0, "Artifact gives on-demand access to AWS's compliance reports.", [null, "Audit Manager collects evidence about your own environment.", "Config tracks your resources' configuration.", "Trusted Advisor checks best practices."]],
["security", "Which service records the history of configuration changes to AWS resources and checks them against rules such as 'all EBS volumes must be encrypted'?", ["AWS Config", "AWS CloudTrail", "Amazon CloudWatch", "AWS Systems Manager"], 0, "Config records resource configurations over time and evaluates them against rules.", [null, "CloudTrail records who made API calls, not ongoing configuration compliance.", "CloudWatch monitors metrics and logs.", "Systems Manager operates and patches instances."]],
["security", "A company needs dedicated, single-tenant hardware to generate and store its encryption keys to meet a strict regulatory requirement. Which service should it use?", ["AWS CloudHSM", "AWS KMS with AWS managed keys", "AWS Secrets Manager", "AWS Certificate Manager"], 0, "CloudHSM gives you dedicated hardware security modules that you control.", [null, "KMS is multi-tenant and AWS managed keys are controlled by AWS.", "Secrets Manager stores secrets; it is not a dedicated HSM.", "ACM manages TLS certificates."]],
["security", "A developer stored a database password in a configuration file in Git. The security team wants passwords stored centrally and changed automatically every 30 days. Which service should they use?", ["AWS Secrets Manager", "Amazon S3 with versioning", "AWS Certificate Manager", "AWS Artifact"], 0, "Secrets Manager stores secrets securely and can rotate them automatically.", [null, "S3 is not designed for secret storage and rotation.", "ACM manages certificates, not passwords.", "Artifact provides compliance documents."]],
["security", "Which feature adds a second layer of protection to the sign-in of IAM users and the root user?", ["Multi-factor authentication (MFA)", "Security groups", "Access Advisor", "Resource tags"], 0, "MFA requires a code from a device in addition to the password.", [null, "Security groups filter network traffic.", "Access Advisor shows service usage.", "Tags label resources."]],
["security", "A company wants one place that collects security findings from GuardDuty, Inspector and Macie across all its accounts and checks against best-practice standards. Which service should it use?", ["AWS Security Hub", "Amazon Detective", "AWS Firewall Manager", "AWS Shield Advanced"], 0, "Security Hub aggregates findings and runs automated best-practice checks.", [null, "Detective helps investigate a finding's root cause.", "Firewall Manager centrally manages firewall rules.", "Shield Advanced protects against DDoS."]],
["security", "A security team notices a suspicious IAM user. It wants to visualize the user's activity over time and quickly understand how the incident happened. Which service helps MOST?", ["Amazon Detective", "AWS Artifact", "AWS Trusted Advisor", "Amazon Macie"], 0, "Detective builds a graph of activity from logs to speed up investigations.", [null, "Artifact provides compliance reports.", "Trusted Advisor checks best practices.", "Macie finds sensitive data in S3."]],
["security", "Which statement about IAM policies is correct?", ["An explicit deny overrides any allow", "An allow in any policy overrides a deny", "Policies can only be attached to groups", "IAM policies are written in YAML only"], 0, "In IAM evaluation, an explicit deny always wins.", [null, "It is the other way round.", "Policies attach to users, groups and roles.", "IAM policies are JSON documents."]],
["security", "A company wants employees to sign in once with their existing corporate identity provider and access several AWS accounts and business apps. Which service should it use?", ["AWS IAM Identity Center", "Amazon Cognito user pools", "IAM users in each account", "AWS Directory Service Simple AD"], 0, "IAM Identity Center provides single sign-on for the workforce across accounts and applications.", [null, "Cognito is designed for customers of your own applications.", "Separate users in each account are hard to manage.", "Simple AD is a basic directory; it is not the multi-account SSO service."]],
["tech", "A company wants to run code only when a new image is uploaded to S3, without managing any servers and paying only for execution time. Which service fits BEST?", ["AWS Lambda", "Amazon EC2", "Amazon Lightsail", "AWS Batch"], 0, "Lambda runs code in response to events such as S3 uploads, billed per request and duration.", [null, "EC2 requires managing servers that run continuously.", "Lightsail runs virtual servers.", "Batch runs batch jobs on compute environments, not small event triggers."]],
["tech", "A team wants to run Docker containers without provisioning or managing EC2 instances. Which option should it choose?", ["Amazon ECS on AWS Fargate", "Amazon ECS on EC2 instances it manages", "Amazon EC2 Auto Scaling", "AWS Elastic Beanstalk with a custom AMI"], 0, "Fargate runs containers serverlessly, so there are no instances to manage.", [null, "With the EC2 launch type you still manage the instances.", "Auto Scaling scales instances; it does not remove them.", "A custom AMI still means EC2 instances."]],
["tech", "A web application's traffic must be spread evenly across EC2 instances in three Availability Zones, and requests should not go to unhealthy instances. What should be used?", ["Elastic Load Balancing", "Amazon Route 53 simple routing", "An Elastic IP address", "AWS Global Accelerator only"], 0, "ELB distributes traffic across healthy targets in multiple AZs.", [null, "Simple routing has no health checks and returns one record.", "An Elastic IP is one address for one instance.", "Global Accelerator routes to endpoints but you'd still use a load balancer to spread traffic across instances."]],
["tech", "Which EC2 purchasing option provides the LARGEST discount for workloads that can handle interruptions?", ["Spot Instances", "On-Demand Instances", "Dedicated Hosts", "Reserved Instances with no upfront payment"], 0, "Spot Instances use spare capacity at up to 90% off but can be reclaimed.", [null, "On-Demand is the full price.", "Dedicated Hosts cost more.", "Reserved discounts are smaller than Spot's and require commitment."]],
["tech", "A beginner wants to launch a simple WordPress website with a predictable monthly price that includes the server, storage and data transfer. Which service is the BEST fit?", ["Amazon Lightsail", "Amazon EC2 with Auto Scaling", "Amazon EKS", "AWS Outposts"], 0, "Lightsail offers simple virtual servers with bundled, predictable pricing.", [null, "EC2 with Auto Scaling is more complex and priced per component.", "EKS runs Kubernetes; far too complex here.", "Outposts places AWS hardware on-premises."]],
["tech", "Which Amazon S3 storage class is the LOWEST cost for data that must be kept for 7 years for compliance and is almost never read, where a retrieval time of up to 48 hours is acceptable?", ["S3 Glacier Deep Archive", "S3 Standard-IA", "S3 Glacier Instant Retrieval", "S3 Intelligent-Tiering"], 0, "Deep Archive is the cheapest class, built for long-term retention with hours to retrieve.", [null, "Standard-IA costs more and is for faster access.", "Instant Retrieval costs more because it gives millisecond access.", "Intelligent-Tiering is for unknown patterns; Deep Archive is cheaper for known archive data."]],
["tech", "A company accidentally overwrote an important file in Amazon S3. Which feature would have let it recover the previous version?", ["S3 Versioning", "S3 Transfer Acceleration", "S3 static website hosting", "S3 Requester Pays"], 0, "Versioning keeps all versions of an object so earlier versions can be restored.", [null, "Transfer Acceleration speeds up uploads.", "Static hosting serves web pages.", "Requester Pays changes who pays for downloads."]],
["tech", "Several Linux EC2 instances in different Availability Zones need to read and write the same set of files at the same time. Which service should be used?", ["Amazon EFS", "Amazon EBS", "Instance store", "Amazon S3 Glacier Deep Archive"], 0, "EFS is a shared NFS file system that many instances across AZs can mount.", [null, "An EBS volume is attached to instances in one AZ (usually one instance).", "Instance store is local to one instance and temporary.", "Deep Archive is archive storage, not a shared file system."]],
["tech", "A company needs to move 300 TB of data from its data center to AWS, but its internet connection would take months. Which service should it use?", ["AWS Snowball Edge", "AWS DataSync over the internet", "Amazon S3 Transfer Acceleration", "AWS Site-to-Site VPN"], 0, "Snowball Edge devices ship data physically when networks are too slow.", [null, "DataSync still uses the slow connection.", "Transfer Acceleration can't exceed the link's bandwidth.", "A VPN runs over the same slow internet link."]],
["tech", "Which AWS service is a fully managed NoSQL key-value database that delivers single-digit millisecond performance at any scale?", ["Amazon DynamoDB", "Amazon RDS for PostgreSQL", "Amazon Redshift", "Amazon Neptune"], 0, "DynamoDB is a serverless key-value and document database.", [null, "RDS for PostgreSQL is relational.", "Redshift is a data warehouse.", "Neptune is a graph database."]],
["tech", "A company's sales team runs complex reports over 5 years of sales history. The reports slow down the production database. Where should the reporting data live?", ["Amazon Redshift", "Amazon ElastiCache", "Amazon DynamoDB", "Amazon EBS"], 0, "Redshift is a data warehouse built for analytics on large historical data.", [null, "ElastiCache is an in-memory cache, not an analytics store.", "DynamoDB is for fast key-value access, not complex reports.", "EBS is block storage for instances."]],
["tech", "Which RDS feature provides a standby copy of the database in another Availability Zone with automatic failover?", ["Multi-AZ deployment", "Read replicas", "Automated backups", "Storage autoscaling"], 0, "Multi-AZ keeps a synchronous standby and fails over automatically.", [null, "Read replicas scale reads; promotion is manual.", "Backups are for restore, not instant failover.", "Storage autoscaling grows disk space."]],
["tech", "A company wants frequently read product data kept in memory to reduce database load and speed up its website. Which service should it use?", ["Amazon ElastiCache", "Amazon S3 Glacier", "AWS Backup", "Amazon Redshift"], 0, "ElastiCache stores data in memory for very fast reads.", [null, "Glacier is archive storage.", "Backup protects data; it doesn't speed up reads.", "Redshift is for analytics."]],
["tech", "Which component allows resources in a public subnet of a VPC to communicate with the internet?", ["Internet gateway", "NAT gateway", "Virtual private gateway", "VPC endpoint"], 0, "An internet gateway attached to the VPC and a route to it make a subnet public.", [null, "A NAT gateway lets private subnets reach out, but itself sits behind the internet gateway.", "A virtual private gateway connects a VPN or Direct Connect.", "VPC endpoints reach AWS services privately."]],
["tech", "Which statement about security groups is correct?", ["They are stateful and support allow rules only", "They are stateless and support deny rules", "They are applied at the subnet level", "They must allow return traffic explicitly"], 0, "Security groups are stateful (return traffic is automatic) and only have allow rules.", [null, "That describes network ACLs.", "Network ACLs apply to subnets; security groups apply to instances (ENIs).", "Return traffic is automatically allowed."]],
["tech", "A company needs a dedicated, private network connection between its data center and AWS with consistent performance. Which service should it use?", ["AWS Direct Connect", "AWS Site-to-Site VPN", "Amazon CloudFront", "AWS Client VPN"], 0, "Direct Connect provides a dedicated private line with consistent bandwidth.", [null, "A Site-to-Site VPN runs over the public internet.", "CloudFront is a CDN.", "Client VPN is for individual users."]],
["tech", "A global news site wants images and videos delivered to readers from locations near them to reduce load times. Which service should it use?", ["Amazon CloudFront", "AWS Direct Connect", "Amazon VPC", "AWS Transit Gateway"], 0, "CloudFront caches content at edge locations worldwide.", [null, "Direct Connect links a data center to AWS.", "A VPC is a private network.", "Transit Gateway connects VPCs and networks."]],
["tech", "Which service translates domain names such as www.example.com into IP addresses and can route users based on latency?", ["Amazon Route 53", "Amazon CloudFront", "AWS Global Accelerator", "Elastic Load Balancing"], 0, "Route 53 is AWS's DNS service with routing policies including latency-based.", [null, "CloudFront delivers content; it is not a DNS service.", "Global Accelerator uses static IPs, not DNS names.", "ELB distributes traffic; it does not resolve domain names."]],
["tech", "An order system must keep orders safe in a queue when the processing servers are busy, so no order is lost. Which service should it use?", ["Amazon SQS", "Amazon SNS", "Amazon CloudWatch", "AWS Step Functions"], 0, "SQS stores messages until consumers process them, decoupling the components.", [null, "SNS pushes notifications; it does not store messages for later processing.", "CloudWatch monitors resources.", "Step Functions orchestrates workflows."]],
["tech", "A call center wants to convert recorded customer calls into text so it can search them. Which service should it use?", ["Amazon Transcribe", "Amazon Polly", "Amazon Translate", "Amazon Rekognition"], 0, "Transcribe converts speech to text.", [null, "Polly converts text to speech.", "Translate converts text between languages.", "Rekognition analyzes images and video."]],
["tech", "A company wants to repeatedly create identical environments (VPC, EC2, RDS) for development, testing and production from template files. Which service should it use?", ["AWS CloudFormation", "AWS Trusted Advisor", "Amazon CloudWatch", "AWS Config"], 0, "CloudFormation provisions infrastructure from templates (infrastructure as code).", [null, "Trusted Advisor gives recommendations.", "CloudWatch monitors.", "Config tracks configuration compliance."]],
["tech", "An operations team wants an alarm and an email when an EC2 instance's CPU usage stays above 80% for 10 minutes. Which services should it use? (Select TWO.)", ["Amazon CloudWatch", "Amazon SNS", "AWS CloudTrail", "AWS Artifact", "Amazon Macie"], [0, 1], "A CloudWatch alarm watches the metric and sends a notification through an SNS topic.", [null, null, "CloudTrail records API activity, not CPU metrics.", "Artifact provides compliance reports.", "Macie finds sensitive data in S3."]],
["billing", "A company wants to estimate the monthly cost of moving its web application to AWS before it creates any resources. Which tool should it use?", ["AWS Pricing Calculator", "AWS Cost Explorer", "AWS Cost and Usage Report", "AWS Budgets"], 0, "The Pricing Calculator estimates costs for planned architectures.", [null, "Cost Explorer analyzes costs you've already incurred.", "The CUR details past usage.", "Budgets alerts on spend; it doesn't estimate a new design."]],
["billing", "A company has several AWS accounts and wants one bill and combined usage to reach volume discount tiers sooner. What should it use?", ["Consolidated billing in AWS Organizations", "A separate payment card per account", "AWS Marketplace", "AWS Budgets"], 0, "Consolidated billing combines usage across accounts for one bill and shared volume discounts.", [null, "Separate payment methods don't combine usage.", "Marketplace is for buying third-party software.", "Budgets sets alerts; it doesn't combine bills."]],
["billing", "Which AWS pricing principle is true for data transfer?", ["Data transferred into AWS from the internet is generally free", "Data transferred out to the internet is always free", "All data transfer between Regions is free", "Data transfer is charged per API call"], 0, "Inbound data transfer is generally free; outbound and inter-Region transfer are charged.", [null, "Outbound data transfer is charged per GB.", "Inter-Region transfer is charged.", "Transfer is charged per GB, not per API call."]],
["billing", "A finance manager wants a graph of the last 12 months of AWS spending by service and a forecast for next month. Which tool should she use?", ["AWS Cost Explorer", "AWS Pricing Calculator", "AWS Artifact", "AWS Health Dashboard"], 0, "Cost Explorer visualizes historical costs and forecasts future spend.", [null, "The Pricing Calculator estimates new designs.", "Artifact provides compliance reports.", "The Health Dashboard shows service events."]],
["billing", "Which AWS Support plan is the LOWEST cost option that includes 24/7 phone, email and chat access to Cloud Support Engineers?", ["Business", "Developer", "Basic", "Enterprise"], 0, "Business (now Business Support+) is the entry tier for 24/7 phone and chat access.", [null, "Developer gives business-hours email support only.", "Basic has no technical support cases.", "Enterprise has it too but costs more."]],
["billing", "A company wants proactive guidance from a designated technical point of contact who knows its workloads, and a 15-minute response time for business-critical outages. Which plan meets this?", ["Enterprise", "Enterprise On-Ramp", "Business", "Developer"], 0, "Enterprise includes a designated TAM and a 15-minute response for business-critical system down.", [null, "Enterprise On-Ramp gives a pool of TAMs and a 30-minute response.", "Business has no TAM.", "Developer has no TAM and limited support."]],
["billing", "A company wants to buy a third-party firewall appliance and pay for it through its AWS bill. Where can it find and subscribe to the product?", ["AWS Marketplace", "AWS Partner Network directory only", "AWS Artifact", "AWS Service Catalog"], 0, "AWS Marketplace lists third-party software that you can buy and run on AWS, billed through AWS.", [null, "The APN lists partners but is not where you subscribe to software billed through AWS.", "Artifact provides compliance reports.", "Service Catalog manages your organization's own approved products."]],
["billing", "A developer is new to AWS and has a quick technical question. She wants free answers from the community and AWS experts. Where should she go?", ["AWS re:Post", "AWS Professional Services", "AWS Concierge Support team", "A Technical Account Manager"], 0, "re:Post is AWS's free community question-and-answer site.", [null, "Professional Services is paid consulting.", "Concierge is part of Enterprise support and focuses on billing.", "TAMs are part of Enterprise-level plans."]]);
MOCK_SETS.push({ n: 2, start: EXAM.length, count: 65 });
EXAM.push(["concepts", "A logistics company used to buy servers every three years based on its best guess of future demand. After moving to AWS, it pays monthly for what it uses. Which advantage of cloud computing is this?", ["Trade fixed expense for variable expense", "Go global in minutes", "Increase speed and agility", "Use edge locations"], 0, "Paying for usage instead of buying hardware up front swaps capital expense for variable expense.", [null, "The scenario is about how the company pays, not about global reach.", "Agility is about how fast you can experiment.", "Edge locations are about content delivery."]],
["concepts", "Why can AWS offer lower prices than most companies could achieve running their own data centers?", ["AWS aggregates usage from hundreds of thousands of customers, achieving economies of scale", "AWS uses only refurbished hardware", "AWS charges a fixed price that never changes", "AWS does not need to secure its facilities"], 0, "Massive combined usage lets AWS buy and operate at a scale that lowers per-unit costs.", [null, "That is not how AWS lowers costs.", "AWS prices change, and have often dropped over time.", "AWS invests heavily in physical security."]],
["concepts", "A gaming company in Manila wants to launch its game for players in Europe and Latin America this month without building data centers there. Which advantage of the cloud does this show?", ["Go global in minutes", "Stop spending money running and maintaining data centers", "Trade fixed expense for variable expense", "Benefit from massive economies of scale"], 0, "AWS Regions around the world let you deploy close to users in minutes.", [null, "That is a benefit too, but the scenario is about reaching new geographies quickly.", "This is about payment, not geography.", "This explains lower prices."]],
["concepts", "Which Well-Architected pillar includes the design principle 'automatically recover from failure'?", ["Reliability", "Security", "Cost optimization", "Sustainability"], 0, "Reliability covers recovering from failures and meeting demand.", [null, "Security covers protecting information and systems.", "Cost optimization covers avoiding unnecessary cost.", "Sustainability covers environmental impact."]],
["concepts", "A team performs operations as code, makes small frequent reversible changes and learns from operational failures. Which Well-Architected pillar is it following?", ["Operational excellence", "Performance efficiency", "Reliability", "Security"], 0, "These are design principles of the Operational excellence pillar.", [null, "Performance efficiency is about using resources efficiently.", "Reliability is about recovering from failure.", "Security is about protecting systems and data."]],
["concepts", "Which are benefits of using AWS managed services such as Amazon RDS instead of running software yourself on EC2? (Select TWO.)", ["AWS handles routine tasks such as patching and backups", "The customer gets full root access to the database host", "Teams can focus more on the application instead of infrastructure", "The customer becomes responsible for the physical hardware", "The service never needs to be configured"], [0, 2], "Managed services offload undifferentiated heavy lifting so teams focus on business value.", [null, "Managed services usually do NOT give OS-level root access.", null, "Physical hardware is always AWS's responsibility.", "You still configure settings such as instance size and security."]],
["concepts", "A company is unsure how much traffic its new application will receive. Which approach BEST follows cloud best practices?", ["Start small and use automatic scaling to adjust capacity", "Buy the largest instances to be safe", "Buy three years of reserved capacity for peak load", "Run the application on a single large server"], 0, "Elastic scaling avoids guessing capacity; you match resources to real demand.", [null, "Oversizing wastes money.", "Committing to peak capacity before knowing demand is risky.", "A single server is a single point of failure and does not scale."]],
["concepts", "Which statement BEST describes an Availability Zone?", ["One or more discrete data centers with redundant power, networking and connectivity in a Region", "A global network of locations that cache content", "A separate AWS account for each team", "A country where AWS operates"], 0, "AZs are isolated groups of data centers within a Region.", [null, "That describes edge locations.", "Accounts are not AZs.", "A country may contain a Region, but an AZ is part of a Region."]],
["concepts", "A video platform needs very low latency for users in one large city where there is no AWS Region nearby. Which infrastructure option places AWS compute closer to those users?", ["AWS Local Zones", "Additional Availability Zones in the home Region", "AWS Organizations", "Amazon S3 Transfer Acceleration"], 0, "Local Zones put compute, storage and database services near large population centers.", [null, "AZs stay inside the existing Region.", "Organizations manages accounts.", "Transfer Acceleration speeds up S3 uploads, not compute latency."]],
["concepts", "A hospital requires that some workloads stay in its own building but wants to use the same AWS APIs and tools as in the cloud. Which service fits?", ["AWS Outposts", "AWS Wavelength", "Amazon CloudFront", "AWS Snowmobile"], 0, "Outposts brings AWS infrastructure and services into the customer's own facility.", [null, "Wavelength places compute inside telecom 5G networks.", "CloudFront is a CDN.", "Snowmobile was a data transfer truck, not on-premises compute."]],
["concepts", "In the AWS Cloud Adoption Framework, which phase identifies capability gaps across the six perspectives and creates plans to address them?", ["Align", "Envision", "Launch", "Scale"], 0, "Align finds capability gaps and cross-organizational dependencies.", [null, "Envision identifies opportunities.", "Launch delivers pilots.", "Scale expands pilots."]],
["concepts", "Which are business perspectives of the AWS Cloud Adoption Framework? (Select TWO.)", ["Governance", "Platform", "Business", "Operations", "Security"], [0, 2], "The business perspectives are Business, People and Governance.", [null, "Platform is a technical perspective.", null, "Operations is a technical perspective.", "Security is a technical perspective."]],
["concepts", "A company will replace its on-premises email server with a SaaS email product instead of migrating the server. Which migration strategy is this?", ["Repurchase", "Rehost", "Replatform", "Retain"], 0, "Repurchase means moving to a different product, usually SaaS.", [null, "Rehost would move the same server to the cloud.", "Replatform would make small changes to the same application.", "Retain would keep it where it is."]],
["concepts", "Which service helps rehost (lift and shift) physical and virtual servers to Amazon EC2 with minimal downtime?", ["AWS Application Migration Service", "AWS Schema Conversion Tool", "AWS Snowball Edge", "Amazon WorkSpaces"], 0, "Application Migration Service continuously replicates servers and cuts over to EC2.", [null, "SCT converts database schemas.", "Snowball moves data offline.", "WorkSpaces provides virtual desktops."]],
["concepts", "What is the main benefit of loose coupling in a cloud architecture?", ["A failure in one component is less likely to cascade to others", "All components must be deployed on the same server", "It removes the need for monitoring", "It guarantees the lowest price"], 0, "Loosely coupled components interact through queues or APIs, so failures stay contained.", [null, "Loose coupling separates components.", "Monitoring is still needed.", "It does not guarantee a price."]],
["concepts", "Which of these is a characteristic of the AWS Cloud's global infrastructure?", ["Each Region is isolated from the other Regions", "All Regions share one set of data centers", "Every service is available in every Region on day one", "Data automatically moves between Regions"], 0, "Regions are isolated for fault tolerance and to keep data where customers put it.", [null, "Regions have their own data centers.", "Service availability varies by Region.", "Data stays in the Region unless the customer copies it."]],
["security", "Under the shared responsibility model, who is responsible for managing the database engine patches on Amazon RDS?", ["AWS", "The customer", "The customer's database vendor", "AWS Professional Services only on request"], 0, "RDS is managed; AWS patches the database engine and underlying OS (during maintenance windows the customer chooses).", [null, "The customer chooses the window but AWS applies the patches.", "AWS manages patching for RDS engines.", "Patching is part of the service itself."]],
["security", "Which customer responsibility stays the same no matter which AWS service is used?", ["Protecting their data and managing who can access it", "Patching the hypervisor", "Maintaining network cabling", "Patching the operating system of managed services"], 0, "Customers always own their data, identities and access configuration.", [null, "The hypervisor is AWS's job.", "Physical networking is AWS's job.", "For managed services, AWS patches the OS."]],
["security", "An intern needs to view EC2 instances but must not start, stop or delete them. Which principle should the administrator apply?", ["Least privilege", "Defense in depth only", "Shared tenancy", "High availability"], 0, "Least privilege grants only the permissions needed for the task.", [null, "Defense in depth layers controls but does not decide what to grant.", "Tenancy is about hardware sharing.", "High availability is about uptime."]],
["security", "What is an IAM role?", ["An identity with permissions that can be assumed to get temporary credentials", "A permanent username and password for a person", "A group of IAM users", "A firewall rule for EC2"], 0, "Roles are assumed by services, users or other accounts and provide temporary credentials.", [null, "That is an IAM user.", "That is an IAM group.", "That is a security group rule."]],
["security", "A mobile banking app needs sign-up and sign-in for millions of customers, including sign-in with Google. Which service should be used?", ["Amazon Cognito", "AWS IAM Identity Center", "IAM users for each customer", "AWS Directory Service"], 0, "Cognito provides customer identity with sign-up, sign-in and social identity providers.", [null, "Identity Center is for the workforce.", "IAM users don't scale to millions of customers and aren't meant for them.", "Directory Service provides Microsoft AD."]],
["security", "Which service lets a company use Microsoft Active Directory in AWS so Windows workloads can join a managed domain?", ["AWS Directory Service", "Amazon Cognito", "AWS Organizations", "AWS Resource Access Manager"], 0, "AWS Directory Service provides managed Microsoft AD.", [null, "Cognito is customer identity for apps.", "Organizations manages accounts.", "RAM shares resources across accounts."]],
["security", "A company wants to set up a new multi-account environment quickly with built-in guardrails, centralized logging and account vending. Which service should it use?", ["AWS Control Tower", "AWS Config only", "Amazon Inspector", "AWS CloudFormation StackSets only"], 0, "Control Tower sets up and governs a secure multi-account landing zone.", [null, "Config evaluates resources but does not build a landing zone.", "Inspector scans for vulnerabilities.", "StackSets deploy templates but don't provide the full governed setup."]],
["security", "Which service automatically scans EC2 instances and container images in Amazon ECR for software vulnerabilities?", ["Amazon Inspector", "Amazon GuardDuty", "AWS Shield", "AWS Artifact"], 0, "Inspector continuously scans workloads for known vulnerabilities and network exposure.", [null, "GuardDuty detects threats from activity.", "Shield protects against DDoS.", "Artifact provides compliance reports."]],
["security", "A company must encrypt data in Amazon S3 using keys whose use is logged and which it can disable if needed. Which service manages these keys?", ["AWS Key Management Service (AWS KMS)", "AWS Certificate Manager", "Amazon Macie", "AWS Secrets Manager"], 0, "KMS creates and controls encryption keys; key usage is logged in CloudTrail.", [null, "ACM manages TLS certificates.", "Macie finds sensitive data.", "Secrets Manager stores secrets like passwords."]],
["security", "A website must use HTTPS. The team wants free public TLS certificates that renew automatically for its load balancer. Which service should it use?", ["AWS Certificate Manager", "AWS KMS", "AWS CloudHSM", "AWS Artifact"], 0, "ACM provides free public certificates for integrated services and renews them automatically.", [null, "KMS manages encryption keys, not TLS certificates.", "CloudHSM is dedicated key hardware.", "Artifact provides compliance documents."]],
["security", "A security team wants to know which user changed a security group last night and from which IP address. Which service should it check?", ["AWS CloudTrail", "Amazon CloudWatch metrics", "AWS Trusted Advisor", "Amazon Inspector"], 0, "CloudTrail records API calls with the identity, time and source IP.", [null, "Metrics show performance, not who made a change.", "Trusted Advisor gives recommendations.", "Inspector scans for vulnerabilities."]],
["security", "A company needs to collect evidence continuously to prepare for a PCI DSS audit of its own AWS environment. Which service helps automate this?", ["AWS Audit Manager", "AWS Artifact", "AWS Shield Advanced", "Amazon Detective"], 0, "Audit Manager continuously collects evidence mapped to compliance frameworks.", [null, "Artifact provides AWS's own reports, not evidence about your environment.", "Shield Advanced is DDoS protection.", "Detective investigates security findings."]],
["security", "A company manages 40 accounts and wants AWS WAF rules and security group policies applied consistently to all of them. Which service should it use?", ["AWS Firewall Manager", "AWS Shield Standard", "Amazon VPC flow logs", "AWS Trusted Advisor"], 0, "Firewall Manager centrally configures firewall rules across accounts in an organization.", [null, "Shield Standard is automatic DDoS protection.", "Flow logs record traffic; they don't enforce rules.", "Trusted Advisor gives recommendations."]],
["security", "Which statement about network ACLs is correct?", ["They are stateless and can contain both allow and deny rules", "They are stateful and allow-only", "They attach directly to EC2 instances", "They replace security groups"], 0, "NACLs are stateless subnet-level filters with numbered allow and deny rules.", [null, "That describes security groups.", "NACLs attach to subnets.", "They complement security groups."]],
["security", "A company discovered that one IP address is attacking its web servers. It wants to block that IP for the whole subnet. What should it use?", ["A network ACL deny rule", "A security group deny rule", "An IAM policy", "A Route 53 health check"], 0, "Network ACLs support deny rules at the subnet level.", [null, "Security groups do not support deny rules.", "IAM controls API permissions, not network traffic.", "Health checks monitor endpoints."]],
["security", "Which AWS service sends alerts about AWS events that may affect your account's resources, such as scheduled maintenance on your EC2 instances?", ["AWS Health Dashboard", "AWS Artifact", "AWS Config", "Amazon Macie"], 0, "The Health Dashboard shows events and maintenance that affect your resources.", [null, "Artifact provides compliance reports.", "Config tracks configuration changes.", "Macie discovers sensitive data."]],
["security", "Which is the BEST way to give a contractor in another AWS account temporary access to a bucket in your account?", ["Create an IAM role they can assume, with only the needed permissions", "Send them your IAM user's access keys", "Make the bucket public for a week", "Give them the root user password"], 0, "Cross-account roles provide temporary, scoped access without sharing credentials.", [null, "Sharing keys removes accountability and can leak.", "Public access exposes data to everyone.", "Root credentials must never be shared."]],
["security", "Where can customers find AWS security bulletins, whitepapers and best-practice guidance in one place?", ["AWS Security Center and the AWS security documentation", "AWS Marketplace", "AWS Cost Explorer", "AWS Service Catalog"], 0, "AWS publishes security resources in its Security Center, blogs, whitepapers and documentation.", [null, "Marketplace sells third-party software.", "Cost Explorer shows spending.", "Service Catalog manages approved products."]],
["security", "A company stores application logs in S3. It must make sure nobody, including administrators, can delete them for 5 years. Which feature should it use?", ["S3 Object Lock in compliance mode", "S3 Lifecycle rules", "S3 Transfer Acceleration", "S3 Intelligent-Tiering"], 0, "Compliance-mode Object Lock prevents deletion by anyone until the retention period ends.", [null, "Lifecycle rules move or delete objects; they don't protect them.", "Transfer Acceleration speeds uploads.", "Intelligent-Tiering changes storage tiers."]],
["tech", "Which are ways to access and manage AWS services? (Select TWO.)", ["AWS Management Console", "AWS Command Line Interface (AWS CLI)", "AWS Artifact", "AWS Marketplace", "Amazon Route 53"], [0, 1], "You can use the console, the CLI, the SDKs and the APIs.", [null, null, "Artifact provides reports.", "Marketplace sells third-party software.", "Route 53 is a DNS service."]],
["tech", "A developer wants to call AWS services from a Python application using native code libraries. What should she use?", ["An AWS SDK", "The AWS Management Console", "AWS Artifact", "AWS Trusted Advisor"], 0, "AWS SDKs provide language-specific libraries for AWS APIs.", [null, "The console is a web interface, not a code library.", "Artifact provides compliance reports.", "Trusted Advisor gives recommendations."]],
["tech", "Which EC2 instance family is BEST for a high-performance web server doing heavy video encoding?", ["Compute optimized", "Memory optimized", "Storage optimized", "Burstable general purpose"], 0, "Compute optimized instances (C family) offer high CPU performance.", [null, "Memory optimized suits in-memory databases.", "Storage optimized suits high local disk I/O.", "Burstable instances suit low, variable CPU."]],
["tech", "A company runs a steady workload 24/7 and knows it will keep running for at least 3 years, on EC2, Fargate and Lambda. Which option offers savings while staying flexible across these services?", ["Compute Savings Plans", "Spot Instances", "Dedicated Hosts", "On-Demand Instances"], 0, "Compute Savings Plans discount EC2, Fargate and Lambda usage in exchange for a commitment.", [null, "Spot can be interrupted and doesn't cover Lambda.", "Dedicated Hosts are for licensing needs.", "On-Demand is the most expensive."]],
["tech", "A company has a software license tied to physical server sockets and must run it on AWS. Which EC2 option should it use?", ["Dedicated Hosts", "Spot Instances", "Shared-tenancy On-Demand Instances", "AWS Lambda"], 0, "Dedicated Hosts give visibility of physical sockets and cores for bring-your-own-license.", [null, "Spot doesn't give host-level visibility.", "Shared tenancy hides the physical host.", "Lambda has no physical server to license."]],
["tech", "What does Amazon EC2 Auto Scaling do?", ["Adds or removes EC2 instances automatically based on demand or schedules", "Increases the size of one instance when CPU is high", "Distributes traffic across instances", "Backs up EBS volumes"], 0, "Auto Scaling adjusts the number of instances.", [null, "That would be vertical scaling, which Auto Scaling does not do.", "That is Elastic Load Balancing.", "That is AWS Backup or snapshots."]],
["tech", "A team wants to deploy a Java web application by uploading its code, and have AWS handle capacity, load balancing, scaling and health monitoring. Which service is BEST?", ["AWS Elastic Beanstalk", "Amazon EC2", "AWS Outposts", "Amazon EKS"], 0, "Elastic Beanstalk is a PaaS that provisions and manages the environment for your code.", [null, "EC2 leaves all setup to you.", "Outposts is on-premises hardware.", "EKS runs Kubernetes, which needs more setup."]],
["tech", "Which service stores Docker container images so ECS and EKS can pull them?", ["Amazon Elastic Container Registry (Amazon ECR)", "Amazon EFS", "AWS CodeBuild", "Amazon S3 Glacier"], 0, "ECR is a managed container image registry.", [null, "EFS is a file system.", "CodeBuild builds and tests code.", "Glacier is archive storage."]],
["tech", "Which storage type should be used for the boot volume of an EC2 instance whose data must survive a stop and start?", ["Amazon EBS", "Instance store", "Amazon S3", "Amazon ElastiCache"], 0, "EBS volumes persist independently of the instance's running state.", [null, "Instance store data is lost when the instance stops.", "S3 is object storage, not a boot volume.", "ElastiCache is an in-memory cache."]],
["tech", "A company wants files that haven't been accessed for 30 days moved to a cheaper S3 storage class automatically, and deleted after one year. What should it configure?", ["An S3 Lifecycle configuration", "S3 Versioning", "S3 Cross-Region Replication", "An S3 bucket policy"], 0, "Lifecycle rules transition and expire objects based on age.", [null, "Versioning keeps old versions.", "Replication copies objects to another bucket.", "Bucket policies control access."]],
["tech", "An on-premises backup application writes to tape. The company wants to replace physical tapes with cloud storage without changing the backup software. Which service should it use?", ["AWS Storage Gateway (Tape Gateway)", "Amazon EFS", "Amazon EBS", "AWS Snowmobile"], 0, "Tape Gateway presents virtual tapes to existing backup software and stores them in AWS.", [null, "EFS is a file system.", "EBS is block storage for EC2.", "Snowmobile was for exabyte-scale one-time transfers."]],
["tech", "A company wants a single place to define backup schedules and retention for EBS, RDS, DynamoDB and EFS. Which service should it use?", ["AWS Backup", "Amazon S3 Glacier Flexible Retrieval", "AWS CloudTrail", "AWS DataSync"], 0, "AWS Backup centrally manages backups across many services.", [null, "Glacier is a storage class, not a backup manager.", "CloudTrail logs API activity.", "DataSync transfers data."]],
["tech", "Which database service is BEST for a social network that needs to query relationships such as 'friends of friends who like the same page'?", ["Amazon Neptune", "Amazon RDS for MySQL", "Amazon Redshift", "Amazon ElastiCache"], 0, "Neptune is a graph database built for highly connected data.", [null, "Relational joins get slow for deep relationship queries.", "Redshift is for analytics.", "ElastiCache is a cache."]],
["tech", "A company uses MongoDB and wants a managed AWS database that is compatible with it. Which service should it choose?", ["Amazon DocumentDB", "Amazon Keyspaces", "Amazon Aurora", "Amazon Timestream"], 0, "DocumentDB is a managed document database with MongoDB compatibility.", [null, "Keyspaces is Cassandra-compatible.", "Aurora is relational.", "Timestream is for time-series data."]],
["tech", "A company must move an Oracle database to Amazon Aurora PostgreSQL. Which services should it use? (Select TWO.)", ["AWS Schema Conversion Tool", "AWS Database Migration Service", "AWS Snowcone", "Amazon CloudFront", "AWS Elastic Beanstalk"], [0, 1], "SCT converts the schema to the new engine; DMS migrates the data.", [null, null, "Snowcone is a small edge device.", "CloudFront is a CDN.", "Beanstalk deploys applications."]],
["tech", "Which component lets EC2 instances in a private subnet download software updates from the internet while blocking connections started from the internet?", ["NAT gateway", "Internet gateway attached directly to the instance", "VPC peering", "AWS Direct Connect"], 0, "A NAT gateway allows outbound-only internet access for private subnets.", [null, "An internet gateway attaches to a VPC, and a direct route would make the subnet public.", "Peering connects VPCs.", "Direct Connect links to on-premises."]],
["tech", "A company has 30 VPCs and two on-premises data centers that all need to connect to each other. Which service simplifies this as a central hub?", ["AWS Transit Gateway", "VPC peering between every pair", "Internet gateways", "Amazon CloudFront"], 0, "Transit Gateway connects many VPCs and on-premises networks through one hub.", [null, "Full-mesh peering is complex and doesn't scale.", "Internet gateways connect to the internet.", "CloudFront is a CDN."]],
["tech", "A company wants to expose its backend functions as REST APIs with throttling and authorization, without managing servers. Which service should it use?", ["Amazon API Gateway", "Elastic Load Balancing", "Amazon Route 53", "AWS Direct Connect"], 0, "API Gateway creates, publishes and secures APIs at any scale.", [null, "ELB balances traffic but is not an API management service.", "Route 53 is DNS.", "Direct Connect is a private network link."]],
["tech", "When a new user signs up, a company wants to send a welcome email, update the CRM and notify the analytics team, all from one published message. Which service fits BEST?", ["Amazon SNS", "Amazon SQS", "Amazon Athena", "AWS Glue"], 0, "SNS publishes one message to many subscribers (fan-out).", [null, "SQS is a queue usually consumed by one consumer type.", "Athena queries data.", "Glue is for ETL."]],
["tech", "A data analyst wants to run SQL queries directly on CSV and Parquet files in S3 without loading them into a database or managing servers. Which service should she use?", ["Amazon Athena", "Amazon RDS", "Amazon EMR", "Amazon ElastiCache"], 0, "Athena is serverless SQL on data in S3.", [null, "RDS needs the data loaded into a database.", "EMR runs big-data clusters you configure.", "ElastiCache is a cache."]],
["tech", "A company needs to process clickstream data from its website in real time as it arrives. Which service should it use?", ["Amazon Kinesis Data Streams", "Amazon S3 Glacier", "AWS Snowball Edge", "Amazon RDS"], 0, "Kinesis ingests and processes streaming data in real time.", [null, "Glacier is archive storage.", "Snowball is offline transfer.", "RDS is a relational database, not a streaming service."]],
["tech", "A retailer wants to recommend products to shoppers using machine learning, but has no ML experts. It wants to build, train and deploy its own models with managed tooling. Which service should it use?", ["Amazon SageMaker AI", "Amazon Polly", "Amazon Lex", "Amazon Comprehend"], 0, "SageMaker AI provides managed tools to build, train and deploy custom ML models.", [null, "Polly is text to speech.", "Lex builds chatbots.", "Comprehend analyzes text."]],
["billing", "A company wants an alert when its monthly AWS cost is forecast to go above its budget of 1,000 USD. Which service should it use?", ["AWS Budgets", "AWS Cost Explorer", "AWS Pricing Calculator", "AWS Organizations"], 0, "Budgets alerts on actual or forecasted cost and usage.", [null, "Cost Explorer shows and forecasts costs but is not the alerting tool.", "The calculator estimates new architectures.", "Organizations manages accounts."]],
["billing", "A finance team needs the most detailed, line-item data about AWS usage and costs to load into its own analytics tools. What should it use?", ["AWS Cost and Usage Report (Data Exports)", "AWS Pricing Calculator", "AWS Health Dashboard", "AWS Trusted Advisor"], 0, "The Cost and Usage Report gives the most granular cost and usage data.", [null, "The calculator estimates future costs.", "The Health Dashboard shows service events.", "Trusted Advisor gives recommendations."]],
["billing", "A company wants to see how much each project costs across many services. What should it do?", ["Apply tags to resources and activate them as cost allocation tags", "Create one VPC per project", "Use a different Region per project", "Use Spot Instances for every project"], 0, "Cost allocation tags let billing reports group costs by tag values such as project.", [null, "VPCs don't separate billing by themselves.", "Regions don't label costs by project.", "Spot changes pricing, not cost reporting."]],
["billing", "Which factors affect the cost of Amazon EC2 On-Demand Instances? (Select TWO.)", ["Instance type and size", "The Region where the instance runs", "The number of IAM users in the account", "The number of security groups", "The AWS Support plan's name"], [0, 1], "Price depends on instance type/size, Region, operating system and running time.", [null, null, "IAM is free and doesn't affect EC2 price.", "Security groups are free.", "The support plan is billed separately."]],
["billing", "Which offering includes always-free services, short-term trials and credits that let new customers explore AWS at no cost?", ["AWS Free Tier", "AWS Marketplace", "Dedicated Hosts", "AWS Professional Services"], 0, "The Free Tier gives new customers free usage and, for newer accounts, credits.", [null, "Marketplace sells software.", "Dedicated Hosts are paid physical servers.", "Professional Services is paid consulting."]],
["billing", "Which AWS Trusted Advisor check category helps reduce costs, for example by finding idle load balancers and underused EC2 instances?", ["Cost optimization", "Fault tolerance", "Service limits", "Security"], 0, "Cost optimization checks find idle and underused resources.", [null, "Fault tolerance checks resilience.", "Service limits checks usage against quotas.", "Security checks find security gaps."]],
["billing", "A company needs help designing and running a large migration and wants experts from AWS to work with its team. What should it use?", ["AWS Professional Services", "AWS re:Post", "AWS Artifact", "AWS Free Tier"], 0, "AWS Professional Services is a team of AWS experts who help customers deliver outcomes.", [null, "re:Post is a community forum.", "Artifact provides compliance reports.", "The Free Tier is free usage, not consulting."]],
["billing", "Which support resource is available to ALL AWS customers, including those on the Basic plan?", ["AWS Trusted Advisor core checks", "A designated Technical Account Manager", "24/7 phone access to Cloud Support Engineers", "Infrastructure Event Management"], 0, "Basic includes core Trusted Advisor checks, the Health Dashboard, documentation and account/billing help.", [null, "TAMs are part of Enterprise-level plans.", "24/7 phone support starts at Business.", "Event management is for higher plans."]]);
