EXAM.push(["concepts", "A school's enrollment portal is busy for two weeks a year and almost idle the rest of the time. Which approach is the MOST cost-effective on AWS?", ["Use automatic scaling so capacity follows demand", "Buy enough reserved capacity for peak enrollment all year", "Run the portal on the largest instance type all year", "Keep the portal on-premises and add servers each year"], 0, "Scaling with demand means paying for peak capacity only while it's needed.", [null, "Reserving peak capacity all year wastes money most of the time.", "An oversized instance costs more and is still one server.", "Buying servers every year is the problem the cloud solves."]],
["concepts", "Which design principle suggests replacing a failed server with a new one from an image instead of repairing it?", ["Treat servers as disposable resources", "Scale vertically", "Use fixed IP addresses", "Run all components on one host"], 0, "Disposable, identical resources can be replaced quickly and automatically.", [null, "Vertical scaling is about bigger servers.", "Fixed IPs tie you to specific servers.", "Running everything on one host creates a single point of failure."]],
["concepts", "Which statement correctly compares high availability and fault tolerance?", ["A fault-tolerant system continues with no interruption; a highly available system keeps downtime minimal", "They mean exactly the same thing", "High availability needs no redundancy", "Fault tolerance is only about backups"], 0, "Fault tolerance aims for zero interruption; high availability minimizes downtime with redundancy and fast recovery.", [null, "They are related but not identical.", "High availability depends on redundancy.", "Backups help recovery but aren't fault tolerance."]],
["concepts", "A company wants to reduce the time between a developer writing code and the code running in production, using automation instead of manual steps. Which Well-Architected pillar does this improve MOST?", ["Operational excellence", "Sustainability", "Cost optimization", "Security"], 0, "Automating deployments and making frequent small changes are operational excellence practices.", [null, "Sustainability is about environmental impact.", "Cost optimization is about spending.", "Security protects data and systems."]],
["concepts", "Which practice belongs to the Security pillar of the Well-Architected Framework?", ["Apply security at all layers", "Use Spot Instances wherever possible", "Scale horizontally to increase availability", "Measure overall efficiency"], 0, "Defense in depth — security at every layer — is a Security pillar principle.", [null, "That is a cost practice.", "That is a reliability principle.", "That is a cost optimization principle."]],
["concepts", "A company's cost team wants to pay only for what it uses and stop spending money on idle resources. Which Well-Architected pillar is this?", ["Cost optimization", "Reliability", "Performance efficiency", "Operational excellence"], 0, "Cost optimization includes adopting a consumption model and eliminating waste.", [null, "Reliability is about recovering from failure.", "Performance efficiency is about using the right resources.", "Operational excellence is about operations."]],
["concepts", "A mobile game needs ultra-low latency for players using 5G phones. Which AWS infrastructure is designed for this?", ["AWS Wavelength", "AWS Outposts", "AWS Local Zones", "Amazon S3 Transfer Acceleration"], 0, "Wavelength embeds AWS compute inside telecom providers' 5G networks.", [null, "Outposts is for on-premises data centers.", "Local Zones are near cities but not inside 5G networks.", "Transfer Acceleration is for S3 uploads."]],
["concepts", "When choosing an AWS Region, which factors should a company consider? (Select TWO.)", ["Proximity to its users for lower latency", "Whether the services it needs are available there", "The number of IAM users it has", "The name of its AWS Support plan", "The color of the AWS console theme"], [0, 1], "Region choice considers compliance, latency, service availability and price.", [null, null, "IAM users are global and not a Region factor.", "Support plans apply to the account, not Regions.", "This is unrelated."]],
["concepts", "Which AWS CAF perspective focuses on making sure IT services meet the needs of the business through monitoring, incident management and performance?", ["Operations", "Business", "Governance", "People"], 0, "The Operations perspective covers how cloud services are run and supported.", [null, "Business aligns cloud investments with business outcomes.", "Governance covers program management, risk and cost.", "People covers culture and skills."]],
["concepts", "A company decides that an old reporting application has no users and turns it off as part of its cloud migration. Which strategy is this?", ["Retire", "Retain", "Rehost", "Relocate"], 0, "Retire means decommissioning applications that are no longer needed.", [null, "Retain keeps the application where it is.", "Rehost moves it as-is.", "Relocate moves VMs as-is (e.g. VMware) to the cloud."]],
["concepts", "A company plans to break a large monolithic application into microservices using Lambda and DynamoDB as part of its move to AWS. Which migration strategy is this?", ["Refactor", "Rehost", "Replatform", "Repurchase"], 0, "Refactoring re-architects the application to be cloud-native.", [null, "Rehost keeps the app unchanged.", "Replatform makes only small optimizations.", "Repurchase moves to another product."]],
["concepts", "Which AWS service helps plan a migration by collecting information about on-premises servers, their utilization and their dependencies?", ["AWS Application Discovery Service", "AWS Database Migration Service", "Amazon Inspector", "AWS Snow Family"], 0, "Application Discovery Service gathers inventory and dependency data for planning.", [null, "DMS moves database data.", "Inspector scans vulnerabilities.", "Snow devices move data physically."]],
["concepts", "Which is an example of the AWS Cloud 'stop spending money running and maintaining data centers' benefit?", ["The IT team stops racking servers and replacing power supplies and focuses on customer features", "The company signs a 10-year data center lease", "The company buys extra air conditioning for its server room", "The company hires more staff to replace hard drives"], 0, "AWS handles the heavy lifting of facilities, so teams focus on the business.", [null, "That increases data center spending.", "That increases data center spending.", "That increases data center maintenance."]],
["concepts", "A company wants to test a new feature with only 10% of its users before releasing it to everyone. Which cloud capability makes this easy and cheap?", ["Quickly provisioning a separate environment and routing a share of traffic to it", "Buying new physical servers for the test", "Waiting for the next hardware refresh cycle", "Running the test on the production database server"], 0, "The cloud lets you create environments in minutes and route a percentage of traffic (e.g. weighted routing).", [null, "Buying hardware is slow and costly.", "Waiting slows innovation.", "Testing on production risks outages."]],
["concepts", "Which statement about AWS edge locations is correct?", ["They are used by services such as CloudFront and Route 53 to serve users with lower latency", "They are another name for Availability Zones", "Customers run EC2 instances in them by default", "Each edge location is a full AWS Region"], 0, "Edge locations cache content and answer DNS queries close to users.", [null, "AZs are inside Regions; edge locations are separate sites.", "EC2 doesn't run in standard edge locations.", "Edge locations are much smaller than Regions."]],
["concepts", "A company wants to know what its total cost of ownership (TCO) would be in AWS compared with its own data center, including power, cooling and staff. Which is the BEST description of this activity?", ["Building a cloud business case using TCO analysis", "Running a penetration test", "Creating an IAM password policy", "Setting up a CloudWatch alarm"], 0, "A TCO comparison looks at all direct and indirect costs, not just server prices.", [null, "Penetration testing checks security.", "Password policies are about IAM.", "Alarms monitor resources."]],
["security", "A company uses AWS Lambda. Under the shared responsibility model, which is the customer's responsibility?", ["The function code and the permissions given to the function", "Patching the operating system that runs the function", "Scaling the underlying servers", "Physical security of the servers"], 0, "With serverless, AWS runs and patches the infrastructure; customers own code, data and IAM permissions.", [null, "AWS patches the underlying OS for Lambda.", "AWS scales Lambda automatically.", "Physical security is AWS's job."]],
["security", "Which are 'shared controls' that both AWS and the customer handle, each for their own layer? (Select TWO.)", ["Patch management", "Configuration management", "Physical data center access", "Customer data classification", "Hypervisor maintenance"], [0, 1], "Patch management, configuration management, and awareness & training are shared controls.", [null, null, "Physical access is AWS only.", "Data classification is the customer's only.", "Hypervisors are AWS only."]],
["security", "A company wants users to change their IAM passwords every 90 days and use at least 14 characters. What should the administrator configure?", ["An IAM password policy", "A service control policy", "An S3 bucket policy", "A security group"], 0, "The account password policy sets complexity, length, expiry and reuse rules for IAM users.", [null, "SCPs limit permissions in accounts.", "Bucket policies control S3 access.", "Security groups filter network traffic."]],
["security", "An administrator wants to see, for one IAM user, which services they are allowed to use and when they last used each one, to remove unnecessary permissions. Which feature should be used?", ["IAM Access Advisor", "IAM Credential Report", "AWS Artifact", "Amazon Macie"], 0, "Access Advisor shows permitted services and last-accessed information.", [null, "The Credential Report lists credential status for all users.", "Artifact provides compliance reports.", "Macie discovers sensitive data."]],
["security", "Which tasks REQUIRE the AWS account root user? (Select TWO.)", ["Change the account's AWS Support plan", "Close the AWS account", "Launch an EC2 instance", "Create an S3 bucket", "Read CloudWatch metrics"], [0, 1], "Some account-level tasks, such as changing the support plan and closing the account, need root.", [null, null, "Any user with permissions can launch instances.", "Any user with permissions can create buckets.", "Any user with permissions can read metrics."]],
["security", "A company's security policy says AWS resources may only be created in two approved Regions across all accounts. What is the MOST effective way to enforce this?", ["A service control policy that denies actions outside the approved Regions", "Asking developers to check the Region before creating resources", "A CloudWatch dashboard per Region", "Tagging resources with the Region name"], 0, "An SCP with a Region condition blocks any action outside approved Regions in every member account.", [null, "A manual check is not enforcement.", "Dashboards show data but don't block anything.", "Tags label resources but don't restrict them."]],
["security", "Which service shares resources such as subnets or Transit Gateways with other accounts in an organization, so they don't need to be duplicated?", ["AWS Resource Access Manager (AWS RAM)", "AWS Artifact", "Amazon Cognito", "AWS Service Catalog"], 0, "RAM shares supported resources across accounts.", [null, "Artifact provides compliance reports.", "Cognito handles application user identity.", "Service Catalog offers approved products, not resource sharing."]],
["security", "A security group allows inbound HTTPS from anywhere. A user can load the website, and the responses reach the user without any outbound rule being added. Why?", ["Security groups are stateful, so return traffic is allowed automatically", "Security groups allow all traffic by default", "The network ACL creates the outbound rule", "HTTPS never needs outbound traffic"], 0, "Stateful filtering automatically allows responses to allowed requests.", [null, "Security groups deny inbound traffic by default.", "NACLs don't create security group rules.", "Responses do travel outbound; they're allowed because of statefulness."]],
["security", "A company must protect its public API from large DDoS attacks, get 24/7 access to the AWS DDoS response team and receive cost protection for scaling during attacks. Which service should it use?", ["AWS Shield Advanced", "AWS Shield Standard", "Amazon GuardDuty", "AWS WAF only"], 0, "Shield Advanced adds advanced DDoS protection, the response team and cost protection.", [null, "Standard gives basic protection without the response team or cost protection.", "GuardDuty detects threats but doesn't mitigate DDoS.", "WAF filters web requests but doesn't include DDoS response or cost protection."]],
["security", "Which AWS service automatically detects unusual API activity, such as an IAM user suddenly launching many instances in an unfamiliar Region?", ["Amazon GuardDuty", "AWS Config", "AWS Trusted Advisor", "Amazon Inspector"], 0, "GuardDuty uses anomaly detection and threat intelligence on account activity.", [null, "Config tracks configuration compliance, not suspicious behavior.", "Trusted Advisor gives best-practice checks.", "Inspector scans for vulnerabilities."]],
["security", "Which type of encryption key does the customer create and manage in AWS KMS, with control over its key policy and rotation?", ["Customer managed key", "AWS managed key", "AWS owned key", "SSE-S3 key"], 0, "Customer managed keys give the customer full control.", [null, "AWS managed keys are created for services; their policy can't be changed.", "AWS owned keys are not visible to customers.", "SSE-S3 keys are managed entirely by S3."]],
["security", "Data must be encrypted while it travels between users' browsers and a web application. What is this called, and what provides it?", ["Encryption in transit, using TLS certificates such as those from AWS Certificate Manager", "Encryption at rest, using AWS KMS", "Tokenization, using Amazon Cognito", "Hashing, using AWS Config"], 0, "Data moving over a network is protected in transit with TLS/HTTPS.", [null, "At-rest encryption protects stored data.", "Cognito handles identity, not transport encryption.", "Config tracks configuration."]],
["security", "Which statements about AWS compliance are correct? (Select TWO.)", ["AWS's compliance reports are available through AWS Artifact", "Using AWS makes every customer workload compliant automatically", "Customers remain responsible for configuring their own workloads to meet compliance", "AWS stores customer data in all Regions to meet regulations", "Compliance is entirely AWS's responsibility"], [0, 2], "AWS certifies its infrastructure (reports in Artifact), but customers must configure their own workloads correctly.", [null, "Compliance of the workload depends on the customer's configuration.", null, "Data stays in the Region the customer chooses.", "Responsibility is shared."]],
["security", "A security engineer wants to run a vulnerability scan against the company's own EC2 instances. What must she do according to AWS policy?", ["Nothing extra; testing your own resources on permitted services is allowed without prior approval", "Request written approval from AWS for every scan", "Purchase AWS Shield Advanced first", "Move the instances to a Dedicated Host"], 0, "AWS allows penetration testing of your own resources on permitted services without prior approval; DoS tests are prohibited.", [null, "Prior approval is no longer needed for permitted services.", "Shield Advanced is not a requirement for testing.", "Tenancy doesn't affect the policy."]],
["security", "Which service helps you check, continuously, whether resources follow rules like 'S3 buckets must not be public', and can trigger automatic remediation?", ["AWS Config rules", "AWS CloudTrail Lake", "AWS Cost Explorer", "Amazon Polly"], 0, "Config rules evaluate compliance and can trigger remediation actions.", [null, "CloudTrail Lake queries API activity.", "Cost Explorer analyzes spend.", "Polly converts text to speech."]],
["security", "An S3 bucket must be readable only by a specific CloudFront distribution, never directly by the public. What is the recommended approach?", ["Keep the bucket private and use CloudFront Origin Access Control", "Make the bucket public and hide the URL", "Use S3 Transfer Acceleration", "Disable S3 Block Public Access"], 0, "Origin Access Control lets CloudFront read a private bucket while blocking direct access.", [null, "Hiding a public URL is not security.", "Transfer Acceleration speeds uploads.", "Disabling Block Public Access increases exposure."]],
["security", "Which AWS service provides a free, central view of security findings and an automated security score against standards such as the AWS Foundational Security Best Practices?", ["AWS Security Hub", "Amazon Inspector", "AWS Firewall Manager", "AWS Audit Manager"], 0, "Security Hub runs automated best-practice checks and aggregates findings into a score.", [null, "Inspector scans for vulnerabilities but doesn't aggregate all services.", "Firewall Manager manages rules.", "Audit Manager collects audit evidence."]],
["security", "A company's employees use a third-party SAML identity provider. It wants them to access the AWS console without creating IAM users. Which approach should it use?", ["Federate the identity provider with IAM Identity Center (or IAM roles)", "Create one shared IAM user for all employees", "Give employees the root user credentials", "Create access keys for each employee"], 0, "Federation lets external identities assume roles with temporary credentials.", [null, "Shared users remove accountability.", "Root must never be shared.", "Long-term keys for everyone are risky and unnecessary."]],
["security", "Who is responsible for reporting AWS resources that are being used for abusive or illegal purposes, such as sending spam?", ["Anyone can report it to the AWS Trust & Safety team", "Only AWS Enterprise customers", "Only the account owner's TAM", "AWS Professional Services"], 0, "AWS Trust & Safety accepts abuse reports from anyone.", [null, "Reporting is open to everyone.", "TAMs are not the abuse channel.", "Professional Services is consulting."]],
["tech", "A company runs a web application on EC2 behind a load balancer. Traffic triples every weekday at 9 AM. Which feature can add instances BEFORE the spike based on the known pattern?", ["Scheduled scaling in EC2 Auto Scaling", "Elastic IP addresses", "Amazon S3 Lifecycle rules", "AWS Config rules"], 0, "Scheduled (or predictive) scaling adds capacity before a known spike.", [null, "Elastic IPs are fixed addresses.", "Lifecycle rules manage S3 objects.", "Config rules check compliance."]],
["tech", "Which load balancer type should be used for HTTP/HTTPS traffic that must be routed to different targets based on the URL path (for example /api and /images)?", ["Application Load Balancer", "Network Load Balancer", "Gateway Load Balancer", "Classic Load Balancer"], 0, "The ALB works at layer 7 and supports path- and host-based routing.", [null, "NLB works at layer 4 (TCP/UDP) without path routing.", "GWLB is for inserting virtual appliances.", "Classic is the legacy option without these features."]],
["tech", "A team wants new EC2 instances to install updates and start a web server automatically the first time they boot. Where should it put the script?", ["EC2 user data", "Instance metadata", "An Elastic IP address", "The instance's security group"], 0, "User data scripts run at first launch.", [null, "Metadata is information the instance reads about itself.", "An Elastic IP is an address.", "Security groups are firewall rules."]],
["tech", "A batch job processes 10,000 files every night and can take up to 3 hours. The company wants AWS to manage job queues and compute capacity. Which service is BEST?", ["AWS Batch", "AWS Lambda", "Amazon Lightsail", "Amazon SNS"], 0, "AWS Batch schedules and runs batch jobs on managed compute.", [null, "Lambda functions time out after 15 minutes.", "Lightsail runs simple servers.", "SNS sends notifications."]],
["tech", "A company already uses Kubernetes on-premises and wants a managed Kubernetes control plane on AWS. Which service should it use?", ["Amazon EKS", "Amazon ECS", "AWS Elastic Beanstalk", "AWS Lambda"], 0, "EKS is managed Kubernetes.", [null, "ECS is AWS's own orchestrator, not Kubernetes.", "Beanstalk deploys applications as a PaaS.", "Lambda runs functions."]],
["tech", "Which S3 storage class is BEST when access patterns are unknown or change over time, and the company wants AWS to move objects between access tiers automatically?", ["S3 Intelligent-Tiering", "S3 One Zone-IA", "S3 Glacier Deep Archive", "S3 Standard"], 0, "Intelligent-Tiering moves objects between tiers based on access.", [null, "One Zone-IA is for infrequent, re-creatable data.", "Deep Archive is for long-term archives.", "Standard doesn't move objects automatically."]],
["tech", "Which S3 storage class is the LOWEST cost option for infrequently accessed data that can be easily re-created if an Availability Zone is lost?", ["S3 One Zone-Infrequent Access", "S3 Standard-Infrequent Access", "S3 Standard", "S3 Intelligent-Tiering"], 0, "One Zone-IA stores data in one AZ at lower cost; good for re-creatable data.", [null, "Standard-IA keeps data across multiple AZs at a higher price.", "Standard is for frequent access.", "Intelligent-Tiering adds monitoring costs and stores across AZs."]],
["tech", "A company wants users around the world to upload large files to one S3 bucket faster, using AWS edge locations. Which feature should it enable?", ["S3 Transfer Acceleration", "S3 Versioning", "S3 Object Lock", "S3 Lifecycle"], 0, "Transfer Acceleration routes uploads through edge locations over the AWS network.", [null, "Versioning keeps object versions.", "Object Lock prevents deletion.", "Lifecycle manages storage classes."]],
["tech", "Windows file servers on-premises need a fully managed replacement in AWS that supports SMB and Active Directory. Which service should be used?", ["Amazon FSx for Windows File Server", "Amazon EFS", "Amazon S3", "Amazon EBS"], 0, "FSx for Windows File Server provides managed SMB file shares with AD integration.", [null, "EFS is NFS for Linux.", "S3 is object storage.", "EBS is block storage for single instances."]],
["tech", "A company wants copies of its servers replicated continuously to AWS so it can recover within minutes if its data center fails. Which service is designed for this?", ["AWS Elastic Disaster Recovery", "AWS Snowball Edge", "Amazon S3 Glacier Flexible Retrieval", "AWS Artifact"], 0, "Elastic Disaster Recovery replicates servers continuously for fast recovery.", [null, "Snowball is for offline bulk transfer.", "Glacier archives data; recovery would be slow.", "Artifact provides compliance reports."]],
["tech", "A read-heavy application on Amazon RDS is slow because of many SELECT queries. The writes are fine. What should be added to improve read performance?", ["RDS read replicas", "Multi-AZ standby", "A larger EBS snapshot", "AWS Shield Advanced"], 0, "Read replicas serve read traffic and offload the primary.", [null, "A Multi-AZ standby is for availability and doesn't serve reads (classic deployment).", "Snapshots are backups.", "Shield protects against DDoS."]],
["tech", "Which database service is MySQL- and PostgreSQL-compatible, stores six copies of data across three Availability Zones and is built by AWS for high performance?", ["Amazon Aurora", "Amazon DynamoDB", "Amazon DocumentDB", "Amazon Redshift"], 0, "Aurora is AWS's cloud-native relational engine with six-way replication.", [null, "DynamoDB is NoSQL.", "DocumentDB is MongoDB-compatible.", "Redshift is a data warehouse."]],
["tech", "A company wants to keep shopping carts in a database that scales automatically to millions of users with millisecond latency, without managing servers. Which service fits BEST?", ["Amazon DynamoDB", "Amazon RDS for Oracle", "Amazon Redshift", "Amazon Neptune"], 0, "DynamoDB is serverless, scales automatically and is ideal for key-value data like carts.", [null, "RDS requires instance sizing and isn't serverless.", "Redshift is for analytics.", "Neptune is for graphs."]],
["tech", "Which are characteristics of a public subnet? (Select TWO.)", ["Its route table has a route to an internet gateway", "Resources in it can have public IP addresses", "It can only contain databases", "It cannot have security groups", "It is shared by all AWS customers"], [0, 1], "A public subnet routes to an internet gateway, and its resources can have public IPs.", [null, null, "Databases usually belong in private subnets.", "Security groups apply in every subnet.", "Subnets belong to your VPC only."]],
["tech", "A company needs to connect its office network to its VPC this week, encrypted over the internet, at low cost. Which option fits BEST?", ["AWS Site-to-Site VPN", "AWS Direct Connect", "Amazon CloudFront", "VPC peering"], 0, "A Site-to-Site VPN can be set up quickly and encrypts traffic over the internet.", [null, "Direct Connect takes weeks to provision.", "CloudFront is a CDN.", "Peering connects VPCs, not offices."]],
["tech", "A multiplayer game uses UDP and players need fixed IP addresses that route them over the AWS global network to the nearest healthy Region. Which service should be used?", ["AWS Global Accelerator", "Amazon CloudFront", "Amazon Route 53 simple routing", "AWS Transit Gateway"], 0, "Global Accelerator provides static anycast IPs and supports TCP and UDP.", [null, "CloudFront focuses on HTTP content delivery.", "Simple routing has no health awareness and no static anycast IPs.", "Transit Gateway connects networks."]],
["tech", "EC2 instances in a private subnet need to reach Amazon S3 without going over the internet. What should be used?", ["A VPC gateway endpoint for S3", "An internet gateway", "AWS Direct Connect", "An Elastic IP address"], 0, "Gateway endpoints give private access to S3 and DynamoDB.", [null, "An internet gateway sends traffic to the internet.", "Direct Connect links on-premises.", "An Elastic IP is a public address."]],
["tech", "A company wants to coordinate several Lambda functions into a workflow with retries, error handling and a manual approval step. Which service should it use?", ["AWS Step Functions", "Amazon SQS", "Amazon SNS", "Amazon Kinesis"], 0, "Step Functions orchestrates multi-step workflows with retries and branching.", [null, "SQS is a queue.", "SNS sends notifications.", "Kinesis streams data."]],
["tech", "A company wants a contact center in the cloud that its agents can use from a browser, set up in minutes and paid per use. Which service should it use?", ["Amazon Connect", "Amazon SES", "Amazon WorkSpaces", "Amazon Lex"], 0, "Amazon Connect is a cloud contact center.", [null, "SES sends email.", "WorkSpaces provides virtual desktops.", "Lex builds chatbots (which can work with Connect)."]],
["tech", "Employees need secure Windows desktops they can use from any device, managed centrally by IT. Which service should be used?", ["Amazon WorkSpaces", "Amazon AppStream 2.0", "Amazon Lightsail", "AWS Amplify"], 0, "WorkSpaces provides managed virtual desktops.", [null, "AppStream streams individual applications, not full desktops.", "Lightsail runs simple servers.", "Amplify builds web and mobile apps."]],
["tech", "Which AWS service gives employees a generative AI assistant that can answer questions, summarize documents and help write code using company data?", ["Amazon Q", "Amazon Polly", "Amazon Translate", "AWS Glue"], 0, "Amazon Q is AWS's generative AI assistant for business and developers.", [null, "Polly converts text to speech.", "Translate translates text.", "Glue is for ETL."]],
["tech", "A company wants to find and fix performance bottlenecks by tracing requests as they travel through its microservices. Which service should it use?", ["AWS X-Ray", "AWS CloudTrail", "AWS Config", "AWS Trusted Advisor"], 0, "X-Ray traces requests across distributed applications.", [null, "CloudTrail records API calls.", "Config tracks configuration.", "Trusted Advisor gives best-practice checks."]],
["billing", "Which pricing model offers the GREATEST discount on EC2 in exchange for a 1- or 3-year commitment, while allowing changes in instance family and Region?", ["Compute Savings Plans", "EC2 Instance Savings Plans", "On-Demand Instances", "Dedicated Hosts On-Demand"], 0, "Compute Savings Plans are the most flexible commitment-based discount.", [null, "Instance Savings Plans give a bigger discount but lock the family and Region.", "On-Demand has no discount.", "Dedicated Hosts are for licensing."]],
["billing", "Which statement about Reserved Instances is correct?", ["They provide a discount compared with On-Demand in exchange for a 1- or 3-year term", "They can be interrupted by AWS with two minutes' notice", "They are free for the first year", "They only apply to Lambda"], 0, "Reserved Instances discount steady usage in exchange for a term commitment.", [null, "That describes Spot Instances.", "They are not free.", "They apply to EC2, RDS and other services, not Lambda."]],
["billing", "A company receives an unexpected spike in charges caused by a misconfigured resource. Which service could have detected the unusual spend automatically using machine learning?", ["AWS Cost Anomaly Detection", "AWS Pricing Calculator", "AWS Artifact", "AWS Systems Manager"], 0, "Cost Anomaly Detection uses ML to find unusual spending and alert you.", [null, "The calculator estimates planned costs.", "Artifact provides compliance reports.", "Systems Manager operates instances."]],
["billing", "Which AWS Support plan includes access to a pool of Technical Account Managers and a 30-minute response time for business-critical system outages?", ["Enterprise On-Ramp", "Enterprise", "Business", "Developer"], 0, "Enterprise On-Ramp provides a pool of TAMs and 30-minute business-critical response.", [null, "Enterprise has a designated TAM and 15-minute response.", "Business has no TAM.", "Developer has no TAM."]],
["billing", "Which AWS Support plan provides the Concierge Support team for billing and account questions?", ["Enterprise", "Business", "Developer", "Basic"], 0, "Concierge Support is part of Enterprise-level support.", [null, "Business doesn't include Concierge.", "Developer doesn't include Concierge.", "Basic doesn't include Concierge."]],
["billing", "A company wants to find a certified AWS consulting partner to help build its data platform. Where should it look?", ["AWS Partner Network (AWS Partner Solutions Finder)", "AWS Trusted Advisor", "AWS Cost Explorer", "AWS Health Dashboard"], 0, "The AWS Partner Network lists vetted consulting and technology partners.", [null, "Trusted Advisor gives recommendations.", "Cost Explorer shows spending.", "Health Dashboard shows service events."]],
["billing", "What is a benefit of AWS Organizations consolidated billing? (Select TWO.)", ["Combined usage across accounts can qualify for volume pricing tiers", "One payment method pays for all member accounts", "Every account gets a free Technical Account Manager", "All data transfer becomes free", "SCPs are applied to the management account"], [0, 1], "Consolidated billing gives one bill and aggregates usage for volume discounts.", [null, null, "TAMs come from support plans, not billing.", "Data transfer is still charged.", "SCPs don't affect the management account."]],
["billing", "Which tool helps a team see how much it would pay each month for a planned architecture with 4 EC2 instances, an RDS database and 2 TB of S3, and share the estimate with its manager?", ["AWS Pricing Calculator", "AWS Budgets", "AWS Cost and Usage Report", "AWS Cost Anomaly Detection"], 0, "The Pricing Calculator models planned resources and produces a shareable estimate.", [null, "Budgets alerts on spend.", "The CUR describes past usage.", "Anomaly Detection watches actual spend."]]);
